      if (V && CFG.vatMode === 'inclusive') { net = tot / (1 + V / 100); vat = tot - net; } else if (V && CFG.vatMode === 'exclusive') { net = tot; vat = tot * V / 100; }
      var recv = tot + (CFG.vatMode === 'exclusive' ? vat : 0), ref = o.ref || o._k, outlet = o.outlet || '';
