    BK.cb.forEach(function (c) { var bank = c.book === 'bank' ? '1010' : c.book === 'petty' ? '1005' : '1000', a = Number(c.amount) || 0, contra = c.contra || (c.type === 'in' ? '4900' : '6900'); if (c.type === 'in') { L.push(mk(c.date, bank, a, 0, c.memo, c._k, 'cashbook:' + c.book)); L.push(mk(c.date, contra, 0, a, c.memo, c._k, 'cashbook:' + c.book)); } else { L.push(mk(c.date, contra, a, 0, c.memo, c._k, 'cashbook:' + c.book)); L.push(mk(c.date, bank, 0, a, c.memo, c._k, 'cashbook:' + c.book)); } });
