  async function cfg() { var c = (await db.get('settings/loyalty_config')) || {}; return Object.assign({}, DEF_CFG, c, { tiers: (c.tiers && c.tiers.length ? c.tiers : DEF_TIERS) }); }
  function tierOf(c, spent) { var t = c.tiers[0]; c.tiers.forEach(function (x) { if (spent >= x.min) t = x; }); return t; }
  function waLink(phone, msg) { var p = digits(phone); if (p.length === 11 && p[0] === '0') p = '234' + p.slice(1); return 'https://wa.me/' + p + '?text=' + encodeURIComponent(msg); }

  /* unified customer list: manual + loyalty + order buyers */
